import collections

def solve():
    def get_moves(state):
        state = sorted(state, reverse=True)
        moves = []
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                a, b = state[i], state[j]
                for k in range(1, min(a, b) + 1):
                    new_state = list(state)
                    new_state[i] -= k
                    new_state[j] -= k
                    new_state.append(2 * k)
                    new_state = tuple(sorted([x for x in new_state if x > 0], reverse=True))
                    moves.append(new_state)
        return moves

    def min_boxes(n):
        initial_state = tuple([1] * n)
        visited = {initial_state}
        queue = collections.deque([initial_state])
        min_b = n

        while queue:
            curr = queue.popleft()
            min_b = min(min_b, len(curr))
            if min_b == 1:
                return 1
            for move in get_moves(curr):
                if move not in visited:
                    visited.add(move)
                    queue.append(move)
        return min_b

    for n in range(1, 11):
        print(f"N={n}, min_boxes={min_boxes(n)}")

solve()
